def build_ins(pe: PE) -> tuple[dict, list]:
    """从 RECGET 起分块反汇编;遇不可解码处断开继续,覆盖整个函数区。"""
    ins = []
    start = RECGET
    end = RECGET + SPAN
    cur = start
    while cur < end:
        chunk = disasm(pe, cur, min(0x100, end - cur))
        if not chunk:
            cur += 0x10
            continue
        ins.extend(chunk)
        nxt = int(chunk[-1]["va"], 16) + len(bytes.fromhex(chunk[-1]["bytes"]))
        if nxt <= cur:
            cur += 0x10
        else:
            cur = nxt
    by_va = {int(i["va"], 16): i for i in ins}
    return by_va, ins

