            path.append({"va": f"0x{cur:x}", "note": "跳转到窗口外"})
            return {"tag": tag, "hit": None, "path": path, "status": "out_of_window"}
        t = i["text"]
        path.append({"va": i["va"], "text": t})
        if i["mn"] == "cmp" and i["op"].startswith("edx, 0x"):
            imm = int(i["op"].split(", ")[1], 16)
            nxt = ins[ins.index(i) + 1] if ins.index(i) + 1 < len(ins) else None
            if nxt is None:
                return {"tag": tag, "hit": None, "path": path, "status": "no_jcc"}
            mn, op = nxt["mn"], nxt["op"]
            path.append({"va": nxt["va"], "text": nxt["text"]})
            if mn in ("jg", "jle", "jne", "je"):
                if mn == "jg":
                    take = val > imm
                elif mn == "jle":
                    take = val <= imm
                elif mn == "jne":
                    take = val != imm
                else:  # je
                    take = val == imm
                fall = int(nxt["va"], 16) + len(bytes.fromhex(nxt["bytes"]))
                if take:
                    cur = int(op, 16)
                else:
                    cur = fall
                # je 取跳转 = 命中; jne 不取跳转 = 顺序落入 case 体 = 命中
                if mn == "je" and take:
                    return {"tag": tag, "hit": f"0x{cur:x}", "path": path,
                            "status": "hit"}
                if mn == "jne" and not take:
                    return {"tag": tag, "hit": f"0x{cur:x}", "path": path,
                            "status": "hit"}
                # jne 取跳转时若目标就是公共 reject 尾,继续走
                continue
            if mn == "jmp":
                cur = int(op, 16)
                continue
            return {"tag": tag, "hit": None, "path": path, "status": "unknown"}
        if i["mn"] == "jmp":
            cur = int(i["op"], 16)
            continue
        return {"tag": tag, "hit": None, "path": path, "status": "fell_through"}
    return {"tag": tag, "hit": None, "path": path, "status": "step_limit"}

